pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BossBaby {
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
    function tradingEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);
    BossBaby private bossBaby;
    address private owner;
    uint256 private _tokenAmount;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        bossBaby = BossBaby(TARGET);
        owner = bossBaby.owner();

        // The owner, who is excluded from the trading lock, transfers tokens to the attacker.
        vm.startPrank(owner);
        _tokenAmount = 1000 * 10**bossBaby.decimals();
        bossBaby.transfer(attacker, _tokenAmount);
        vm.stopPrank();

        // Verify the attacker received the tokens.
        assertEq(bossBaby.balanceOf(attacker), _tokenAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Verify the precondition: trading is not enabled.
        assertEq(bossBaby.tradingEnabled(), false);

        // Set the expected revert message.
        vm.expectRevert(bytes("Trading is not enabled yet"));

        // Attacker, who is a regular user, attempts to transfer tokens. This will fail.
        bossBaby.transfer(address(0xdeadbeef), _tokenAmount);
        assertEq(bossBaby.tradingEnabled(), false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

