pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BossBaby {
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
    function tradingEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    BossBaby private bossBaby;
    uint256 private _tokenAmount;
    // The original deployer of the contract, who holds the initial supply.
    address private constant TOKEN_HOLDER = 0xF309252C5855F772596956247c4e51270a4B7f40;
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        bossBaby = BossBaby(TARGET);
        _tokenAmount = 1000 * 10**bossBaby.decimals();

        // The original deployer/token holder is excluded from fees and can transfer.
        vm.startPrank(TOKEN_HOLDER);
        bossBaby.transfer(attacker, _tokenAmount);
        vm.stopPrank();

        // Verify the attacker received the tokens. Since the sender is excluded, there are no fees.
        assertEq(bossBaby.balanceOf(attacker), _tokenAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Verify the precondition: trading is not enabled.
        assertEq(bossBaby.tradingEnabled(), false);

        // Expect the transfer to fail because the attacker is not excluded from fees
        // and trading is not enabled.
        vm.expectRevert(bytes("Trading is not enabled yet"));

        // Attacker, a regular user, attempts to transfer tokens. This must fail.
        bossBaby.transfer(address(0xdeadbeef), _tokenAmount);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

